export default function Footer() {
  const linkStyle = {
    fontFamily: "'Inter', sans-serif",
    fontSize: "14px",
    color: "rgba(255,255,255,0.55)",
    textDecoration: "none",
    display: "block",
    marginBottom: "14px",
    cursor: "pointer",
  };

  const headingStyle = {
    fontFamily: "'Inter', sans-serif",
    fontSize: "15px",
    fontWeight: 700,
    color: "white",
    marginBottom: "24px",
  };

  const boldLinkStyle = {
    fontFamily: "'Inter', sans-serif",
    fontSize: "13px",
    fontWeight: 700,
    color: "white",
    marginBottom: "6px",
  };

  const emailStyle = {
    fontFamily: "'Inter', sans-serif",
    fontSize: "13px",
    color: "rgba(255,255,255,0.55)",
    display: "flex",
    alignItems: "center",
    gap: "8px",
    marginBottom: "20px",
  };

  const MailIcon = () => (
    <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
      stroke="rgba(255,255,255,0.55)" strokeWidth="2">
      <rect x="2" y="4" width="20" height="16" rx="2" />
      <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7" />
    </svg>
  );

  return (
    <footer style={{
      background: "#0a0a0f",
      padding: "60px 80px 40px",
    //   borderTop: "1px solid rgba(255,255,255,0.08)",
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
    }}>

      {/* Logo */}
      <div style={{ display: "flex", justifyContent: "center", marginBottom: "48px" }}>
        <img src="/assets/logo.png" alt="IDfy" style={{ height: "56px", width: "auto" }} />
      </div>

      {/* Divider */}
      <div style={{
        borderTop: "1px solid rgba(255,255,255,0.08)",
        marginBottom: "48px",
        width: "100%",
        maxWidth: "1100px",
      }} />

      {/* Main grid — centered */}
      <div style={{
        width: "100%",
        maxWidth: "1100px",
      }}>

        {/* Row 1: Contact Info | About Us | Platforms */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "1.2fr 1fr 1fr",
          gap: "48px 32px",
          marginBottom: "48px",
        }}>

          {/* Contact Info */}
          <div>
            <p style={headingStyle}>Contact info</p>

            <p style={boldLinkStyle}>For Sales</p>
            <p style={emailStyle}><MailIcon /> shivani@idfy.com</p>

            <p style={boldLinkStyle}>For Support</p>
            <p style={emailStyle}><MailIcon /> support@idfy.com</p>

            <p style={boldLinkStyle}>For Partnerships</p>
            <p style={emailStyle}><MailIcon /> vishal.suri@idfy.com</p>
          </div>

          {/* About Us */}
          <div>
            <p style={headingStyle}>About Us</p>
            {["Company", "Our Team", "Our Investors", "Partners", "Careers"].map(item => (
              <a key={item} href="#" style={linkStyle}>{item}</a>
            ))}
          </div>

          {/* Platforms */}
          <div>
            <p style={headingStyle}>Platforms</p>
            {["OnboardIQ", "OneRisk", "Privy"].map(item => (
              <a key={item} href="#" style={linkStyle}>{item}</a>
            ))}
          </div>
        </div>

        {/* Row 2: Resources | Industries | Corporate */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "1.2fr 1fr 1fr",
          gap: "48px 32px",
        }}>

          {/* Resources */}
          <div>
            <p style={headingStyle}>Resources</p>
            {["Blogs", "Learning Hub"].map(item => (
              <a key={item} href="#" style={linkStyle}>{item}</a>
            ))}
          </div>

          {/* Industries — two-column internal grid */}
          <div>
            <p style={headingStyle}>Industries</p>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }}>
              {[
                "Banking", "Consumer Goods",
                "Payment Acquirers", "Retail",
                "Payment Issuers", "eCommerce",
                "Motor Insurance", "Logistics",
                "Health Insurance", "Vehicle Loans",
                "Life Insurance", "Housing loans",
              ].map(item => (
                <a key={item} href="#" style={linkStyle}>{item}</a>
              ))}
            </div>
          </div>

          {/* Corporate — now in row 2 col 3, below Platforms */}
          <div>
            <p style={headingStyle}>Corporate</p>
            {[
              "Privacy Policy", "Terms of Use",
              "MSA", "Contact Us",
              "BGV Cost Calculator", "Sitemap",
            ].map(item => (
              <a key={item} href="#" style={linkStyle}>{item}</a>
            ))}
          </div>

        </div>
      </div>

      {/* Bottom bar */}
      <div style={{
        borderTop: "1px solid rgba(255,255,255,0.08)",
        marginTop: "48px",
        paddingTop: "24px",
        width: "100%",
        maxWidth: "1100px",
        display: "flex",
        justifyContent: "center",
      }}>
        <p style={{
          fontFamily: "'Inter', sans-serif",
          fontSize: "13px",
          color: "rgba(255,255,255,0.35)",
          margin: 0,
        }}>
          © {new Date().getFullYear()} IDfy. All rights reserved.
        </p>
      </div>

    </footer>
  );
}
